        <tr>
          <th>A: Top 20% Revenue</th>
          <td class="ax-cell"><strong>AX</strong><br>Cash cows<br>Review weekly</td>
          <td class="az-cell"><strong>AY</strong><br>Seasonal stars<br>Budget buffer</td>
          <td><strong>AZ</strong><br>Promotion-driven<br>Order small, often</td>
        </tr>
        <tr>
          <th>B: Mid 30% Revenue</th>
          <td><strong>BX</strong><br>Steady earners<br>Standard reorder</td>
          <td><strong>BY</strong><br>Watch closely<br>Flexible safety stock</td>
          <td><strong>BZ</strong><br>Unreliable income<br>Consider drop-ship</td>
        </tr>
        <tr>
          <th>C: Bottom 50% Revenue</th>
          <td><strong>CX</strong><br>Niche staples<br>Low cost to hold</td>
          <td><strong>CY</strong><br>Marginal &amp; variable<br>Minimal stock</td>
          <td class="cx-cell"><strong>CZ</strong><br>Cash traps<br>Drop or make-to-order</td>
        </tr>
