function overlap(a,b){
  if(!a||!b) return false;
  const vOverlap = a.top < b.bottom && b.top < a.bottom;
  const hOverlap = a.left < b.right && b.left < a.right;
  return vOverlap && hOverlap;
}

(async () => {
  const browser = await puppeteer.launch({executablePath: EXEC, headless: 'shell',
    args:['--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--window-size=1920,1080']});
  const page = await browser.newPage();
  await page.setViewport({width:1920,height:1080});
  await page.goto(URL, {waitUntil:'load', timeout:60000});
  await new Promise(r=>setTimeout(r,2000)); // let GSAP + fonts settle

  async function seekAndMeasure(t, ids){
    await page.evaluate((t)=>{ const tl=window.__timelines&&window.__timelines.main; if(tl){tl.pause(); try{tl.totalTime(t,true);}catch(e){tl.seek(t);} } }, t);
    await new Promise(r=>setTimeout(r,400));
    return await page.evaluate((ids)=>{
      const o={};
      for(const id of ids){const el=document.getElementById(id); if(!el){o[id]=null;continue;}
        const cs=getComputedStyle(el); if(cs.opacity==='0'||cs.visibility==='hidden'){o[id]={hidden:true};continue;}
        const r=el.getBoundingClientRect(); o[id]={top:Math.round(r.top),bottom:Math.round(r.bottom),left:Math.round(r.left),right:Math.round(r.right),h:Math.round(r.height)};}
      return o;
    }, ids);
  }

  const s1 = await seekAndMeasure(6, ['s1-kick','s1-h1','s1-h2','s1-sub']);
  const s2 = await seekAndMeasure(13, ['s2-kick','s2-h','s2-sub']);
  console.log('SCENE1 @6s:', JSON.stringify(s1,null,0));
  console.log('SCENE2 @13s:', JSON.stringify(s2,null,0));

  // check pairwise overlaps among visible text blocks
  function checkScene(name, boxes){
    const keys=Object.keys(boxes).filter(k=>boxes[k]&&!boxes[k].hidden);
    let bad=[];
    for(let i=0;i<keys.length;i++)for(let j=i+1;j<keys.length;j++){
      if(overlap(boxes[keys[i]],boxes[keys[j]])) bad.push(keys[i]+' <> '+keys[j]);
    }
    console.log(name+' overlaps: '+(bad.length?bad.join(', '):'NONE ✓'));
  }
  checkScene('SCENE1', s1);
  checkScene('SCENE2', s2);
  await browser.close();
})().catch(e=>{console.error('ERR',e);process.exit(1);});
